import{_ as i,C as t,o as n,c as o,a2 as e,E as l}from"./chunks/framework.B_GyVC5q.js";const m=JSON.parse('{"title":"macOS desktop first launch","description":"","frontmatter":{"title":"macOS desktop first launch"},"headers":[],"relativePath":"guide/macos-desktop.md","filePath":"guide/macos-desktop.md"}'),r={name:"guide/macos-desktop.md"};function p(h,s,d,c,k,u){const a=t("MacosQuarantineScript");return n(),o("div",null,[s[0]||(s[0]=e('<h1 id="macos-desktop-first-launch" tabindex="-1">macOS desktop first launch <a class="header-anchor" href="#macos-desktop-first-launch" aria-label="Permalink to &quot;macOS desktop first launch&quot;">​</a></h1><p>Desktop builds from GitHub Releases are <strong>ad-hoc signed</strong> but <strong>not Apple-notarized</strong>. After download, macOS Gatekeeper may say the app <em>can’t be opened</em> or is <em>damaged</em>.</p><p>Clear the quarantine attribute, then open the app. Prefer <strong>Terminal</strong> (commands you paste are not blocked the same way as double-clicking a downloaded helper script).</p><h2 id="quarantine-fix-script-per-release" tabindex="-1">Quarantine fix script (per release) <a class="header-anchor" href="#quarantine-fix-script-per-release" aria-label="Permalink to &quot;Quarantine fix script (per release)&quot;">​</a></h2><p>Each GitHub Release publishes its own <code>fix-macos-quarantine.sh</code> (stamped with that version). The same file is inside the macOS ZIP. Use the script that matches the app you downloaded — not an older or newer release’s copy.</p>',5)),l(a),s[1]||(s[1]=e(`<h3 id="install-with-terminal" tabindex="-1">Install with Terminal <a class="header-anchor" href="#install-with-terminal" aria-label="Permalink to &quot;Install with Terminal&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/midrissi/4d-dataexplorer/releases/latest/download/install-desktop.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>Windows (PowerShell):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">midrissi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dataexplorer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">releases</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">download</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">install-desktop.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p>Or use the <strong>Install via Terminal</strong> tabs on the docs home Download control (your OS is preselected).</p><h3 id="quarantine-fix-only" tabindex="-1">Quarantine fix only <a class="header-anchor" href="#quarantine-fix-only" aria-label="Permalink to &quot;Quarantine fix only&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/midrissi/4d-dataexplorer/releases/latest/download/fix-macos-quarantine.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>For a specific tag (example <code>v1.2.3</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/midrissi/4d-dataexplorer/releases/download/v1.2.3/fix-macos-quarantine.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>The script looks for <code>Data Explorer.app</code> in the current folder, <code>/Applications</code>, <code>~/Downloads</code>, and <code>~/Desktop</code>, then runs <code>xattr -cr</code> and opens the app.</p><h3 id="run-xattr-yourself" tabindex="-1">Run xattr yourself <a class="header-anchor" href="#run-xattr-yourself" aria-label="Permalink to &quot;Run xattr yourself&quot;">​</a></h3><p>If the app is already in Applications:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/Data Explorer.app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/Data Explorer.app&quot;</span></span></code></pre></div><p>If it is still in the unzipped folder — type <code>cd</code> then a space, drag the folder into Terminal, press Return, then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Data Explorer.app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Data Explorer.app&quot;</span></span></code></pre></div><h2 id="zip-contents" tabindex="-1">ZIP contents <a class="header-anchor" href="#zip-contents" aria-label="Permalink to &quot;ZIP contents&quot;">​</a></h2><p>Each macOS desktop ZIP from CI includes:</p><ul><li><code>Data Explorer.app</code> — the application</li><li><code>README.html</code> — offline guide (URLs stamped for that release)</li><li><code>fix-macos-quarantine.sh</code> — the same per-version script (run via <code>bash</code>, not double-click)</li></ul><h2 id="copy-a-browser-session" tabindex="-1">Copy a browser session <a class="header-anchor" href="#copy-a-browser-session" aria-label="Permalink to &quot;Copy a browser session&quot;">​</a></h2><p>On the <strong>Connection screen</strong>, fill the <strong>Server URL</strong> then use <strong>Sign-in</strong> on the right of the field. Data Explorer opens <code>/rest/$singleton/CopySession/copySession</code> in a browser (copy the link, or open it in Chrome / Firefox / Safari / Edge). Confirm on the 4D page to send the session cookies back to the app. <a href="/4d-dataexplorer/guide/parts.html#connection-screen">Named parts</a>.</p><p>Install the <code>CopySession</code> shared singleton class in your 4D project (use <strong>Download CopySession class</strong> from the Sign in menu and drop <code>CopySession.4dm</code> into <code>Project/Sources/Classes/</code>). Edit the trusted URL list at the top of that class if the callback is not localhost.</p><p>Optional: keep a one-line datastore wrapper so <code>/rest/$catalog/copySession</code> still works:</p><div class="language-4d vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">4d</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exposed onHTTPGet Function copySession($callbackUrl : Text; $state : Text) : 4D.OutgoingMessage</span></span>
<span class="line"><span>	return cs.CopySession.me.copySession($callbackUrl; $state)</span></span></code></pre></div><p>Default trusted callbacks: <code>http://localhost:*</code>, <code>http://127.0.0.1:*</code>, their <code>https</code> variants, and <code>dataexplorer://*</code> (mobile).</p><h2 id="page-zoom-and-links" tabindex="-1">Page zoom and links <a class="header-anchor" href="#page-zoom-and-links" aria-label="Permalink to &quot;Page zoom and links&quot;">​</a></h2><ul><li><strong>Zoom</strong> — View menu Zoom In / Out / Reset, or ⌘/Ctrl + <code>+</code> / <code>-</code> / <code>0</code>. Pinch or ⌘/Ctrl + scroll zooms only while the gesture <strong>started</strong> with ⌘ or Ctrl (trackpad inertia after you release the modifier does not keep zooming).</li><li><strong>External links</strong> — <code>https</code>, <code>http</code>, and <code>mailto</code> links open in the system browser (WebView ignores <code>target=&quot;_blank&quot;</code>). Rebuild after permission changes so the opener allowlist applies.</li></ul><h2 id="related-links" tabindex="-1">Related links <a class="header-anchor" href="#related-links" aria-label="Permalink to &quot;Related links&quot;">​</a></h2><ul><li><a href="https://github.com/midrissi/4d-dataexplorer/releases" target="_blank" rel="noreferrer">GitHub Releases</a></li><li><a href="/4d-dataexplorer/guide/getting-started.html">Getting started</a> (web / Docker install)</li><li>Template source: <a href="https://github.com/midrissi/4d-dataexplorer/blob/main/apps/desktop/scripts/fix-macos-quarantine.sh" target="_blank" rel="noreferrer"><code>apps/desktop/scripts/fix-macos-quarantine.sh</code></a></li></ul>`,28))])}const b=i(r,[["render",p]]);export{m as __pageData,b as default};
